import{_ as s,o as a,c as e,a0 as n}from"./chunks/framework.BxrwG5q5.js";const k=JSON.parse('{"title":"Documentation Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md"}'),t={name:"guide/versioning.md"};function l(o,i,r,h,p,d){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="documentation-versioning" tabindex="-1">Documentation Versioning <a class="header-anchor" href="#documentation-versioning" aria-label="Permalink to &quot;Documentation Versioning&quot;">​</a></h1><p>This page explains how @jewel998/config handles versioning for the platform, SDK, and documentation.</p><h2 id="version-scheme" tabindex="-1">Version Scheme <a class="header-anchor" href="#version-scheme" aria-label="Permalink to &quot;Version Scheme&quot;">​</a></h2><p>The project follows <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a> (semver):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAJOR.MINOR.PATCH</span></span>
<span class="line"><span>  │      │     │</span></span>
<span class="line"><span>  │      │     └── Bug fixes, documentation updates (no breaking changes)</span></span>
<span class="line"><span>  │      └──────── New features, backward-compatible additions</span></span>
<span class="line"><span>  └─────────────── Breaking changes (require migration)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Component</th><th>Current Version</th><th>Published To</th></tr></thead><tbody><tr><td>SDK (<code>@jewel998/config</code>)</td><td>0.2.x</td><td>npm</td></tr><tr><td>Monorepo (portal, functions, docs)</td><td>0.1.x</td><td>Self-hosted via git</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Pre-1.0 Versioning</p><p>While the project is pre-1.0, minor versions (0.x.0) may include breaking changes. After 1.0.0, only major versions will break backward compatibility. We document all breaking changes in the <a href="/config/guide/migrations.html">Migration Guides</a>.</p></div><h2 id="how-versioning-works" tabindex="-1">How Versioning Works <a class="header-anchor" href="#how-versioning-works" aria-label="Permalink to &quot;How Versioning Works&quot;">​</a></h2><h3 id="sdk-versioning" tabindex="-1">SDK Versioning <a class="header-anchor" href="#sdk-versioning" aria-label="Permalink to &quot;SDK Versioning&quot;">​</a></h3><p>The SDK (<code>@jewel998/config</code>) is published to npm with independent version numbers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @jewel998/config</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pin to specific version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @jewel998/config@0.2.1</span></span></code></pre></div><p>The SDK version is independent of the backend version. We maintain backward compatibility between SDK and API — older SDKs work with newer backends, and newer SDKs work with older backends (within the same major version).</p><h3 id="platform-versioning-self-hosted" tabindex="-1">Platform Versioning (Self-Hosted) <a class="header-anchor" href="#platform-versioning-self-hosted" aria-label="Permalink to &quot;Platform Versioning (Self-Hosted)&quot;">​</a></h3><p>Since you self-host the portal and Cloud Functions, your deployment version is tied to the git commit you&#39;re running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check your current version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List available versions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v*&quot;</span></span></code></pre></div><h3 id="config-data-versioning" tabindex="-1">Config Data Versioning <a class="header-anchor" href="#config-data-versioning" aria-label="Permalink to &quot;Config Data Versioning&quot;">​</a></h3><p>Each environment maintains a <code>configVersion</code> counter that increments on every change:</p><ul><li>The SDK polls <code>/api/v1/version</code> to check the current version number</li><li>If the version hasn&#39;t changed, no full config fetch is needed (saves bandwidth and cost)</li><li>The version is per-environment — changes in staging don&#39;t affect production&#39;s version</li></ul><h2 id="updating-your-deployment" tabindex="-1">Updating Your Deployment <a class="header-anchor" href="#updating-your-deployment" aria-label="Permalink to &quot;Updating Your Deployment&quot;">​</a></h2><h3 id="standard-update-no-breaking-changes" tabindex="-1">Standard Update (No Breaking Changes) <a class="header-anchor" href="#standard-update-no-breaking-changes" aria-label="Permalink to &quot;Standard Update (No Breaking Changes)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>This is safe for patch and minor version bumps.</p><h3 id="breaking-change-update" tabindex="-1">Breaking Change Update <a class="header-anchor" href="#breaking-change-update" aria-label="Permalink to &quot;Breaking Change Update&quot;">​</a></h3><p>When a new version includes breaking changes:</p><ol><li>Check the <a href="/config/guide/migrations.html">Migration Guide</a> for the target version</li><li>Back up your Firestore data (see <a href="/config/guide/backup-restore.html">Backup &amp; Restore</a>)</li><li>Review the migration steps</li><li>Apply the update:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run any migration scripts mentioned in the guide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><h3 id="rolling-back" tabindex="-1">Rolling Back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling Back&quot;">​</a></h3><p>If something goes wrong after an update:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Roll back to previous version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or whatever version you were on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Your Firestore data is not modified by code deployments — only Cloud Functions and Hosting artifacts change. Rolling back code is always safe.</p><h2 id="version-compatibility-matrix" tabindex="-1">Version Compatibility Matrix <a class="header-anchor" href="#version-compatibility-matrix" aria-label="Permalink to &quot;Version Compatibility Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SDK Version</th><th>API Version</th><th>Compatible?</th><th>Notes</th></tr></thead><tbody><tr><td>0.2.x</td><td>0.1.x</td><td>✅</td><td>Full compatibility</td></tr><tr><td>0.1.x</td><td>0.2.x</td><td>✅</td><td>Older SDK works with newer API</td></tr><tr><td>1.x (future)</td><td>0.x</td><td>❌</td><td>Major version boundary</td></tr></tbody></table><h2 id="breaking-change-policy" tabindex="-1">Breaking Change Policy <a class="header-anchor" href="#breaking-change-policy" aria-label="Permalink to &quot;Breaking Change Policy&quot;">​</a></h2><p>We commit to:</p><ol><li><strong>No silent breaking changes</strong> — Every breaking change gets a migration guide</li><li><strong>Deprecation notices</strong> — Features marked deprecated in one minor version before removal</li><li><strong>Data preservation</strong> — Firestore data is never wiped or restructured without an explicit migration script</li><li><strong>SDK grace period</strong> — Old SDK versions continue working for at least 2 minor API versions after deprecation</li></ol><h2 id="documentation-versions" tabindex="-1">Documentation Versions <a class="header-anchor" href="#documentation-versions" aria-label="Permalink to &quot;Documentation Versions&quot;">​</a></h2><p>This documentation site always reflects the latest version. For older versions:</p><ul><li>Check the <code>docs/</code> folder at a specific git tag: <code>git checkout v0.1.0 -- apps/docs/</code></li><li>Or browse the repository at a tag on GitHub: <code>github.com/jewel998/config/tree/v0.1.0/apps/docs</code></li></ul><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><p>All changes are tracked via <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> in the git history:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View recent changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2 weeks ago&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View changes for a specific component</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/config/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> functions/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/portal/</span></span></code></pre></div><p>Release notes are published with each GitHub release tag.</p>`,42)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
